// Build a valid Shape with rank in [0, kMaxRank]. Ensure all referenced dims are initialized.
// Keep dimension sizes small to avoid overflow while still exercising multiplication paths.
{
  gpu::Shape shape;
  const size_t maxRank = gpu::Shape::kMaxRank;
  size_t rank = (*FUZZ_PARAM(unsigned int)) % (maxRank + 1);
  shape.rank = rank;
  for (size_t i = 0; i < rank; ++i) {
    // Dimensions in [0, 8] to explore zero and positive sizes without overflow.
    shape.data[i] = (*FUZZ_PARAM(unsigned int)) % 9;
  }
  // Compute expected product locally and assert gpu::size matches it.
  size_t expected = 1;
  for (size_t i = 0; i < rank; ++i) {
    // Safe product within small bounds; if a dim is zero, product becomes zero.
    expected *= shape.data[i];
  }
  size_t got = gpu::size(shape);
  FUZZ_ASSERT(got == expected, "gpu::size must equal the product of dims up to rank");
}
// No persistent objects to return.

// Generate a NumType, sometimes invalid, and verify size in bytes for valid cases.
{
  unsigned int sel = (*FUZZ_PARAM(unsigned int)) % 5; // 0..4
  gpu::NumType t = gpu::kf32;
  if (sel == 0) t = gpu::kf16;
  else if (sel == 1) t = gpu::kf32;
  else if (sel == 2) t = gpu::ki32;
  else t = static_cast<gpu::NumType>(99); // intentionally invalid

  size_t sz = gpu::sizeBytes(t);
  if (t == gpu::kf16) {
    FUZZ_ASSERT(sz == 2, "kf16 must be 2 bytes");
  } else if (t == gpu::kf32 || t == gpu::ki32) {
    FUZZ_ASSERT(sz == 4, "kf32/ki32 must be 4 bytes");
  } else {
    // Invalid enum values should return 0 per API.
    FUZZ_ASSERT(sz == 0, "Invalid NumType should yield 0 bytes");
  }
}
// No outputs.

// Exercise all overloads of toString.
{
  // NumType -> string
  unsigned int sel = (*FUZZ_PARAM(unsigned int)) % 5;
  gpu::NumType t = (sel == 0 ? gpu::kf16 : sel == 1 ? gpu::kf32 : sel == 2 ? gpu::ki32 : static_cast<gpu::NumType>(77));
  std::string tn = gpu::toString(t);
  // For valid enums, ensure strings match expected tokens.
  if (t == gpu::kf16) {
    FUZZ_ASSERT(tn == std::string("f16"), "kf16 should stringify to f16");
  } else if (t == gpu::kf32) {
    FUZZ_ASSERT(tn == std::string("f32"), "kf32 should stringify to f32");
  } else if (t == gpu::ki32) {
    FUZZ_ASSERT(tn == std::string("i32"), "ki32 should stringify to i32");
  }

  // Shape -> string
  gpu::Shape s;
  s.rank = (*FUZZ_PARAM(unsigned int)) % (gpu::Shape::kMaxRank + 1);
  for (size_t i = 0; i < s.rank; ++i) s.data[i] = (*FUZZ_PARAM(unsigned int)) % 10; // small dims
  std::string ss = gpu::toString(s);
  // If rank==0, expect empty string; otherwise ensure commas count is rank-1.
  if (s.rank == 0) {
    FUZZ_ASSERT(ss.empty(), "Rank-0 shape should stringify to empty");
  } else {
    size_t commas = 0; for (char c : ss) if (c == ',') ++commas;
    FUZZ_ASSERT(commas == (s.rank > 0 ? s.rank - 1 : 0), "Comma count should be rank-1");
  }

  // size_t -> string
  size_t v = *FUZZ_PARAM(size_t);
  std::string vs = gpu::toString(v);
  // Ensure vs parses back to the same value via stoull when possible.
  try {
    unsigned long long back = std::stoull(vs);
    FUZZ_ASSERT(back == v, "Round-trip toString(size_t) should match");
  } catch (...) {
    FUZZ_BAIL();
  }
}
// No outputs.

// Exercise both replaceAll overloads with constraints.
{
  // Single pattern replacement
  std::string str1 = FUZZ_PARAM_STR();
  std::string from = FUZZ_PARAM_STR();
  std::string to = FUZZ_PARAM_STR();
  if (from.empty()) { FUZZ_BAIL(); }
  std::string before = str1;
  gpu::replaceAll(str1, from, to);
  // If from != to, all occurrences of 'from' should be eliminated.
  if (from != to) {
    FUZZ_ASSERT(str1.find(from) == std::string::npos, "All occurrences of 'from' must be replaced");
  }

  // Multiple replacements in sequence
  std::string str2 = FUZZ_PARAM_STR();
  // Build up to 3 replacement pairs with non-empty patterns.
  std::vector<std::pair<std::string, std::string>> reps;
  for (int i = 0; i < 3; ++i) {
    std::string f = FUZZ_PARAM_STR();
    if (f.empty()) continue; // enforce non-empty pattern per API guidance
    std::string t = FUZZ_PARAM_STR();
    reps.emplace_back(f, t);
  }
  if (reps.empty()) { FUZZ_BAIL(); }
  const std::string res = gpu::replaceAll(str2, reps);
  // Basic sanity: the function returns the mutated string (by value) equal to str2 after mutation.
  FUZZ_ASSERT(res == str2, "replaceAll should return the mutated string");
}
// No outputs.

// Generate random inputs and call the checker utility. It should not throw/abort.
{
  bool cond = ((*FUZZ_PARAM(unsigned int)) & 1u) != 0u;
  std::string msg = FUZZ_PARAM_STR();
  std::string file = FUZZ_PARAM_STR();
  int line = static_cast<int>(*FUZZ_PARAM(unsigned int));
  gpu::check(cond, msg.c_str(), file.c_str(), line);
}
// No outputs.

// size_t ceiling division
{
  size_t d = (*FUZZ_PARAM(unsigned int)) % 1024u + 1u; // ensure d > 0
  size_t n = *FUZZ_PARAM(size_t);
  size_t q = gpu::cdiv(n, d);
  // Verify q is the smallest integer such that q*d >= n.
  FUZZ_ASSERT(q * d >= n, "cdiv: q*d must be >= n");
  if (q > 0) {
    FUZZ_ASSERT((q - 1) * d < n, "cdiv: (q-1)*d must be < n when q>0");
  }
}

// Shape element-wise ceiling division
{
  gpu::Shape total;
  gpu::Shape group;
  size_t rank = (*FUZZ_PARAM(unsigned int)) % (gpu::Shape::kMaxRank + 1);
  total.rank = rank;
  group.rank = rank;
  for (size_t i = 0; i < rank; ++i) {
    total.data[i] = (*FUZZ_PARAM(unsigned int)) % 1024u; // allow zero totals
    group.data[i] = ((*FUZZ_PARAM(unsigned int)) % 16u) + 1u; // require > 0
  }
  gpu::Shape out = gpu::cdiv(total, group);
  // Validate per-dimension ceil division property
  for (size_t i = 0; i < rank; ++i) {
    size_t n = total.data[i];
    size_t d = group.data[i];
    size_t q = out.data[i];
    FUZZ_ASSERT(q * d >= n, "shape cdiv: q*d >= n per dimension");
    if (q > 0) {
      FUZZ_ASSERT((q - 1) * d < n || n == 0, "shape cdiv: minimal q per dimension");
    }
  }
}
// No outputs.
